def camel_to_snake(s: str) -> str:
    result = []
    for i, c in enumerate(s):
        if c.isupper() and i > 0:
            result.append('_')
        result.append(c.lower())
    return ''.join(result)

def is_palindrome(s: str) -> bool:
    s = ''.join(char.lower() for char in s if char.isalnum())
    return s == s[::-1]

def valid_parens(s: str) -> bool:
    stack = []
    mapping = {
        ')': '(',
        ']': '[',
        '}': '{'
    }
    for char in s:
        if char in mapping:
            if not stack or stack.pop() != mapping[char]:
                return False
        else:
            stack.append(char)
    return not stack

def flatten(xs: list) -> list:
    result = []
    for x in xs:
        if isinstance(x, list):
            result.extend(flatten(x))
        else:
            result.append(x)
    return result

def word_count(text: str) -> dict:
    words = text.split()
    cleaned_words = [word.strip('!.?').lower() for word in words]
    return dict(word for word in cleaned_words if word)

def run_length_encode(s: str) -> str:
    if not s:
        return ''
    result = ''
    current_char = s[0]
    count = 1
    for char in s[1:]:
        if char == current_char:
            count += 1
        else:
            result += current_char + str(count)
            current_char = char
            count = 1
    result += current_char + str(count)
    return result

def merge_intervals(iv: list) -> list:
    if not iv:
        return []

    # Sort intervals based on start time
    iv.sort(key=lambda x: x[0])

    merged = [iv[0]]

    for current in iv[1:]:
        last = merged[-1]
        if current[0] <= last[1] + 1:
            # Overlapping or touching intervals, merge them
            merged[-1] = [last[0], max(last[1], current[1])]
        else:
            merged.append(current)

    return merged

